<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Audit Logs','subtitle'=>'Recent security-relevant and operational changes.']) ?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Actor</th><th>Action</th><th>Entity</th><th>Message</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= esc(fmt_date($l['created_at'],true)) ?></td><td><?= esc($l['actor_name']??'System') ?></td><td><code><?= esc($l['action']) ?></code></td><td><?= esc($l['entity_type']?:'—') ?><?= $l['entity_id']?' #'.(int)$l['entity_id']:'' ?></td><td><?= esc($l['message']) ?></td></tr><?php endforeach; ?><?php if(empty($logs)): ?><tr><td colspan="5"><div class="empty">No audit activity has been recorded.</div></td></tr><?php endif; ?></tbody></table></div></section><?= $this->endSection() ?>
